type TranslationFn = ReturnType<typeof useTranslation>["t"];

type LeaderboardPeriod = DateRangePeriod;
type LeaderboardPresetPeriod = DateRangePresetPeriod;
type LeaderboardTab = "trading" | "positions";
type LeaderboardSort =
  | "ascending_realized_pnl"
  | "descending_realized_pnl"
  | "ascending_perp_volume"
  | "descending_perp_volume";
type LeaderboardSortableColumn = "perp_volume" | "realized_pnl";
type LeaderboardColumn = {
  key: string;
  label: string;
  defaultVisible?: boolean;
};

type LeaderboardState = {
  period: LeaderboardPeriod;
  startDate: string;
  endDate: string;
  address: string;
  pageSize: string;
  sort: LeaderboardSort;
};

type LeaderboardRow = {
  [key: string]: unknown;
  rank?: number;
  address?: string;
  account_id?: string;
  broker_id?: string;
  date?: string;
  perp_volume?: number | string;
  perp_taker_volume?: number | string;
  perp_maker_volume?: number | string;
  total_fee?: number | string;
  broker_fee?: number | string;
  realized_pnl?: number | string;
};

type LeaderboardResponse = {
  success?: boolean;
  message?: string;
  data?: {
    rows?: LeaderboardRow[];
    meta?: {
      total?: number | string;
      current_page?: number | string;
      records_per_page?: number | string;
    };
  };
};

type PositionsLeaderboardState = {
  symbol: string;
  pageSize: string;
};

type PositionsLeaderboardRow = {
  [key: string]: unknown;
  rank?: number;
  account_id?: string;
  address?: string;
  broker_id?: string;
  symbol?: string;
  symbol_hash?: string;
  holding?: number | string;
  total_realized_pnl?: number | string;
  index_price?: number | string;
  mark_price?: number | string;
  holding_value?: number | string;
  opening_cost?: number | string;
  average_entry_price?: number | string;
  un_realized_pnl?: number | string;
};

type PositionsLeaderboardResponse = {
  success?: boolean;
  err_code?: number;
  err_msg?: string | null;
  message?: string;
  data?: {
    rows?: PositionsLeaderboardRow[];
  };
};

const SORTABLE_LEADERBOARD_COLUMNS: LeaderboardSortableColumn[] = [
  "perp_volume",
  "realized_pnl",
];

const LEADERBOARD_COLUMNS = [
  { key: "rank", label: "Rank", defaultVisible: true },
  { key: "address", label: "Address", defaultVisible: true },
  { key: "account_id", label: "Account ID", defaultVisible: false },
  { key: "perp_volume", label: "Perp Volume", defaultVisible: true },
  { key: "perp_taker_volume", label: "Taker Volume", defaultVisible: false },
  { key: "perp_maker_volume", label: "Maker Volume", defaultVisible: false },
  { key: "total_fee", label: "Gross Builder Fee", defaultVisible: false },
  { key: "realized_pnl", label: "Realized PnL", defaultVisible: true },
  { key: "broker_id", label: "Broker ID", defaultVisible: false },
  { key: "date", label: "Date", defaultVisible: false },
];

const POSITIONS_LEADERBOARD_COLUMNS: LeaderboardColumn[] = [
  { key: "rank", label: "Rank", defaultVisible: true },
  { key: "address", label: "Address", defaultVisible: true },
  { key: "account_id", label: "Account ID", defaultVisible: false },
  { key: "symbol", label: "Symbol", defaultVisible: true },
  { key: "holding", label: "Holding", defaultVisible: true },
  { key: "holding_value", label: "Holding Value", defaultVisible: true },
  {
    key: "total_realized_pnl",
    label: "Total Realized PnL",
    defaultVisible: true,
  },
  { key: "un_realized_pnl", label: "Unrealized PnL", defaultVisible: true },
  {
    key: "average_entry_price",
    label: "Avg Entry Price",
    defaultVisible: false,
  },
  { key: "mark_price", label: "Mark Price", defaultVisible: false },
  { key: "index_price", label: "Index Price", defaultVisible: false },
  { key: "opening_cost", label: "Opening Cost", defaultVisible: false },
  { key: "broker_id", label: "Broker ID", defaultVisible: false },
  { key: "symbol_hash", label: "Symbol Hash", defaultVisible: false },
];

function getLeaderboardColumnLabel(
  t: TranslationFn,
  columnKey: string,
  fallback: string
) {
  switch (columnKey) {
    case "rank":
      return t("dataAnalytics.leaderboard.column.rank");
    case "address":
      return t("dataAnalytics.column.address");
    case "account_id":
      return t("dataAnalytics.column.accountId");
    case "perp_volume":
      return t("dataAnalytics.leaderboard.column.perpVolume");
    case "perp_taker_volume":
      return t("dataAnalytics.leaderboard.column.takerVolume");
    case "perp_maker_volume":
      return t("dataAnalytics.leaderboard.column.makerVolume");
    case "total_fee":
      return t("dataAnalytics.leaderboard.column.grossBuilderFee");
    case "realized_pnl":
      return t("dataAnalytics.column.realizedPnl");
    case "broker_id":
      return t("dataAnalytics.column.brokerId");
    case "date":
      return t("dataAnalytics.leaderboard.column.date");
    case "symbol":
      return t("dataAnalytics.common.symbol");
    case "holding":
      return t("dataAnalytics.leaderboard.column.holding");
    case "holding_value":
      return t("dataAnalytics.leaderboard.column.holdingValue");
    case "total_realized_pnl":
      return t("dataAnalytics.leaderboard.column.totalRealizedPnl");
    case "un_realized_pnl":
      return t("dataAnalytics.column.unrealizedPnl");
    case "average_entry_price":
      return t("dataAnalytics.leaderboard.column.avgEntryPrice");
    case "mark_price":
      return t("dataAnalytics.column.markPrice");
    case "index_price":
      return t("dataAnalytics.leaderboard.column.indexPrice");
    case "opening_cost":
      return t("dataAnalytics.leaderboard.column.openingCost");
    case "symbol_hash":
      return t("dataAnalytics.leaderboard.column.symbolHash");
    default:
      return fallback;
  }
}

function getLeaderboardColumnLabels(
  t: TranslationFn,
  columns: LeaderboardColumn[]
) {
  return Object.fromEntries(
    columns.map(column => [
      column.key,
      getLeaderboardColumnLabel(t, column.key, column.label),
    ])
  );
}

const ALL_LEADERBOARD_COLUMN_KEYS = LEADERBOARD_COLUMNS.map(
  column => column.key
);
const DEFAULT_VISIBLE_COLUMNS = LEADERBOARD_COLUMNS.filter(
  column => column.defaultVisible
).map(column => column.key);
const ALL_POSITIONS_LEADERBOARD_COLUMN_KEYS = POSITIONS_LEADERBOARD_COLUMNS.map(
  column => column.key
);
const DEFAULT_VISIBLE_POSITIONS_COLUMNS = POSITIONS_LEADERBOARD_COLUMNS.filter(
  column => column.defaultVisible
).map(column => column.key);
const TRADING_LEADERBOARD_TWO_DECIMAL_COLUMNS = [
  "perp_volume",
  "perp_taker_volume",
  "perp_maker_volume",
  "total_fee",
  "realized_pnl",
];
const POSITIONS_LEADERBOARD_TWO_DECIMAL_COLUMNS = ["holding_value"];

function getDefaultState(): LeaderboardState {
  return {
    period: "30d",
    ...getPresetDateRange("30d"),
    address: "",
    pageSize: "20",
    sort: "descending_perp_volume",
  };
}

function getDefaultPositionsState(): PositionsLeaderboardState {
  return {
    symbol: "",
    pageSize: "20",
  };
}

function getDashboardQueryBaseUrl() {
  return getOrderlyEnvConfig().env === "prod"
    ? "https://orderly-dashboard-query-service.orderly.network"
    : "https://dashboard-query.dev.orderly-i.network";
}

function normalizePositiveInteger(value: string, fallback: number) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 1) return fallback;
  return Math.floor(parsed);
}

function isLeaderboardSortableColumn(
  column: string
): column is LeaderboardSortableColumn {
  return SORTABLE_LEADERBOARD_COLUMNS.includes(
    column as LeaderboardSortableColumn
  );
}

function getLeaderboardSortConfig(sort: LeaderboardSort): {
  column: LeaderboardSortableColumn;
  direction: "asc" | "desc";
} {
  if (sort === "ascending_realized_pnl") {
    return { column: "realized_pnl", direction: "asc" };
  }
  if (sort === "descending_realized_pnl") {
    return { column: "realized_pnl", direction: "desc" };
  }
  if (sort === "ascending_perp_volume") {
    return { column: "perp_volume", direction: "asc" };
  }
  return { column: "perp_volume", direction: "desc" };
}

function getLeaderboardSortValue(
  column: LeaderboardSortableColumn,
  direction: "asc" | "desc"
): LeaderboardSort {
  if (column === "realized_pnl") {
    return direction === "asc"
      ? "ascending_realized_pnl"
      : "descending_realized_pnl";
  }
  return direction === "asc"
    ? "ascending_perp_volume"
    : "descending_perp_volume";
}

function getNextLeaderboardSort(
  currentSort: LeaderboardSort,
  column: LeaderboardSortableColumn
) {
  const currentConfig = getLeaderboardSortConfig(currentSort);
  const nextDirection =
    currentConfig.column === column && currentConfig.direction === "desc"
      ? "asc"
      : "desc";
  return getLeaderboardSortValue(column, nextDirection);
}

function orderColumnKeys(
  columnKeys: string[],
  orderedColumnKeys = ALL_LEADERBOARD_COLUMN_KEYS
) {
  const columnKeySet = new Set(columnKeys);
  return orderedColumnKeys.filter(column => columnKeySet.has(column));
}

function buildVisibleLeaderboardPayload(
  payload: LeaderboardResponse | null,
  page: number,
  pageSize: string,
  visibleColumns: string[]
) {
  if (!payload) return null;

  const startRank = (page - 1) * normalizePositiveInteger(pageSize, 20);
  const rows = (payload.data?.rows || []).map((row, index) => {
    const enrichedRow: Record<string, unknown> = {
      ...row,
      rank: startRank + index + 1,
    };

    return visibleColumns.reduce<LeaderboardRow>((nextRow, column) => {
      nextRow[column] = enrichedRow[column] ?? "";
      return nextRow;
    }, {});
  });

  return {
    ...payload,
    data: {
      ...payload.data,
      rows,
    },
  };
}

function buildVisiblePositionsLeaderboardPayload(
  payload: PositionsLeaderboardResponse | null,
  page: number,
  pageSize: string,
  visibleColumns: string[]
) {
  if (!payload) return null;

  const startRank = (page - 1) * normalizePositiveInteger(pageSize, 20);
  const rows = (payload.data?.rows || []).map((row, index) => {
    const enrichedRow: Record<string, unknown> = {
      ...row,
      rank: startRank + index + 1,
    };

    return visibleColumns.reduce<PositionsLeaderboardRow>((nextRow, column) => {
      nextRow[column] = enrichedRow[column] ?? "";
      return nextRow;
    }, {});
  });

  return {
    ...payload,
    data: {
      ...payload.data,
      rows,
    },
  };
}

async function fetchTradingLeaderboard(
  state: LeaderboardState,
  page: number,
  brokerIdRequiredMessage: string
) {
  const brokerId = getAnalyticsBrokerId();
  if (!brokerId) {
    throw new Error(brokerIdRequiredMessage);
  }

  const endpoint = `/v1/broker/leaderboard/daily${buildQueryString({
    start_date: state.startDate,
    end_date: state.endDate,
    page,
    size: normalizePositiveInteger(state.pageSize, 20),
    broker_id: brokerId,
    sort: state.sort,
    address: state.address.trim() || undefined,
    aggregateBy: "address",
  })}`;

  return orderlyApi<LeaderboardResponse>({ endpoint, token: null });
}

async function fetchPositionsLeaderboard(
  state: PositionsLeaderboardState,
  page: number,
  brokerIdRequiredMessage: string
) {
  const brokerId = getAnalyticsBrokerId();
  if (!brokerId) {
    throw new Error(brokerIdRequiredMessage);
  }

  const limit = normalizePositiveInteger(state.pageSize, 30);
  const endpoint = `/ranking/positions${buildQueryString({
    broker_id: brokerId,
    symbol: state.symbol.trim() || undefined,
    offset: (page - 1) * limit,
    limit,
    order_by: "DESC",
  })}`;

  return orderlyApi<PositionsLeaderboardResponse>({
    endpoint,
    baseUrl: getDashboardQueryBaseUrl(),
    token: null,
  });
}

export default function DataAnalyticsLeaderboardPage() {
  const { t } = useTranslation();
  const [filters, setFilters] = useState<LeaderboardState>(() =>
    getDefaultState()
  );
  const [activeLeaderboardTab, setActiveLeaderboardTab] =
    useState<LeaderboardTab>("trading");
  const [positionsFilters, setPositionsFilters] =
    useState<PositionsLeaderboardState>(() => getDefaultPositionsState());
  const [payload, setPayload] = useState<LeaderboardResponse | null>(null);
  const [positionsPayload, setPositionsPayload] =
    useState<PositionsLeaderboardResponse | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [positionsCurrentPage, setPositionsCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [positionsLoading, setPositionsLoading] = useState(false);
  const [error, setError] = useState("");
  const [positionsError, setPositionsError] = useState("");
  const [loadedAt, setLoadedAt] = useState<Date | null>(null);
  const [positionsLoadedAt, setPositionsLoadedAt] = useState<Date | null>(null);
  const [dateRangeOpen, setDateRangeOpen] = useState(false);
  const [visibleColumns, setVisibleColumns] = useState(() => [
    ...DEFAULT_VISIBLE_COLUMNS,
  ]);
  const [visiblePositionsColumns, setVisiblePositionsColumns] = useState(() => [
    ...DEFAULT_VISIBLE_POSITIONS_COLUMNS,
  ]);
  const requestIdRef = useRef(0);
  const positionsRequestIdRef = useRef(0);
  const filtersAutoLoadReadyRef = useRef(false);
  const positionsFiltersAutoLoadReadyRef = useRef(false);
  const previousAddressRef = useRef(filters.address);
  const previousPositionSymbolRef = useRef(positionsFilters.symbol);
  const leaderboardTabItems = useMemo<
    ReadonlyArray<OdsSegmentedControlItem<LeaderboardTab>>
  >(
    () => [
      { value: "trading", label: t("dataAnalytics.leaderboard.tab.trading") },
      {
        value: "positions",
        label: t("dataAnalytics.leaderboard.tab.positions"),
      },
    ],
    [t]
  );
  const leaderboardColumnLabels = useMemo(
    () => getLeaderboardColumnLabels(t, LEADERBOARD_COLUMNS),
    [t]
  );
  const positionsLeaderboardColumnLabels = useMemo(
    () => getLeaderboardColumnLabels(t, POSITIONS_LEADERBOARD_COLUMNS),
    [t]
  );
  const visiblePayload = useMemo(
    () =>
      buildVisibleLeaderboardPayload(
        payload,
        currentPage,
        filters.pageSize,
        visibleColumns
      ),
    [currentPage, filters.pageSize, payload, visibleColumns]
  );
  const visiblePositionsPayload = useMemo(
    () =>
      buildVisiblePositionsLeaderboardPayload(
        positionsPayload,
        positionsCurrentPage,
        positionsFilters.pageSize,
        visiblePositionsColumns
      ),
    [
      positionsCurrentPage,
      positionsFilters.pageSize,
      positionsPayload,
      visiblePositionsColumns,
    ]
  );
  const sortConfig = getLeaderboardSortConfig(filters.sort);
  const positionsRows = positionsPayload?.data?.rows || [];
  const positionsPageSize = normalizePositiveInteger(
    positionsFilters.pageSize,
    20
  );
  const positionsHasNextPage = positionsRows.length >= positionsPageSize;
  function updateFilter<K extends keyof LeaderboardState>(
    key: K,
    value: LeaderboardState[K]
  ) {
    setFilters(current => ({ ...current, [key]: value }));
  }

  function updatePositionsFilter<K extends keyof PositionsLeaderboardState>(
    key: K,
    value: PositionsLeaderboardState[K]
  ) {
    setPositionsFilters(current => ({ ...current, [key]: value }));
  }

  function updatePeriod(period: LeaderboardPresetPeriod) {
    setFilters(current => {
      return { ...current, period, ...getPresetDateRange(period) };
    });
  }

  function updateCustomDateRange(startDate: string, endDate: string) {
    setFilters(current => ({
      ...current,
      period: "custom",
      startDate,
      endDate,
    }));
  }

  function toggleColumn(column: string) {
    setVisibleColumns(current => {
      if (current.includes(column)) {
        if (current.length === 1) return current;
        return current.filter(item => item !== column);
      }
      return orderColumnKeys([...current, column]);
    });
  }

  function togglePositionsColumn(column: string) {
    setVisiblePositionsColumns(current => {
      if (current.includes(column)) {
        if (current.length === 1) return current;
        return current.filter(item => item !== column);
      }
      return orderColumnKeys(
        [...current, column],
        ALL_POSITIONS_LEADERBOARD_COLUMN_KEYS
      );
    });
  }

  function toggleAllColumns() {
    setVisibleColumns(current =>
      current.length === ALL_LEADERBOARD_COLUMN_KEYS.length
        ? [...DEFAULT_VISIBLE_COLUMNS]
        : [...ALL_LEADERBOARD_COLUMN_KEYS]
    );
  }

  function toggleAllPositionsColumns() {
    setVisiblePositionsColumns(current =>
      current.length === ALL_POSITIONS_LEADERBOARD_COLUMN_KEYS.length
        ? [...DEFAULT_VISIBLE_POSITIONS_COLUMNS]
        : [...ALL_POSITIONS_LEADERBOARD_COLUMN_KEYS]
    );
  }

  function handleSortChange(column: string) {
    if (!isLeaderboardSortableColumn(column)) return;
    setCurrentPage(1);
    updateFilter("sort", getNextLeaderboardSort(filters.sort, column));
  }

  async function loadLeaderboard(page = 1, filtersOverride = filters) {
    const validationError = validateDateRange(
      filtersOverride.startDate,
      filtersOverride.endDate
    );
    if (validationError) {
      setError(validationError);
      return;
    }

    const requestId = requestIdRef.current + 1;
    requestIdRef.current = requestId;
    setLoading(true);
    setError("");
    setLoadedAt(null);

    try {
      const response = await fetchTradingLeaderboard(
        filtersOverride,
        page,
        t("dataAnalytics.leaderboard.error.brokerIdRequired")
      );
      if (requestIdRef.current !== requestId) return;
      if (response.success === false) {
        throw new Error(
          response.message || t("dataAnalytics.leaderboard.error.failedToLoad")
        );
      }
      setPayload(response);
      setCurrentPage(page);
      setLoadedAt(new Date());
    } catch (err) {
      if (requestIdRef.current !== requestId) return;
      setPayload(null);
      setError(
        err instanceof Error
          ? err.message
          : t("dataAnalytics.leaderboard.error.failedToLoad")
      );
    } finally {
      if (requestIdRef.current === requestId) setLoading(false);
    }
  }

  async function loadPositionsLeaderboard(
    page = 1,
    filtersOverride = positionsFilters
  ) {
    const requestId = positionsRequestIdRef.current + 1;
    positionsRequestIdRef.current = requestId;
    setPositionsLoading(true);
    setPositionsError("");
    setPositionsLoadedAt(null);

    try {
      const response = await fetchPositionsLeaderboard(
        filtersOverride,
        page,
        t("dataAnalytics.leaderboard.error.positionsBrokerIdRequired")
      );
      if (positionsRequestIdRef.current !== requestId) return;
      if (
        response.success === false ||
        (typeof response.err_code === "number" && response.err_code !== 0)
      ) {
        throw new Error(
          response.err_msg ||
            response.message ||
            t("dataAnalytics.leaderboard.error.failedToLoadPositions")
        );
      }
      setPositionsPayload(response);
      setPositionsCurrentPage(page);
      setPositionsLoadedAt(new Date());
    } catch (err) {
      if (positionsRequestIdRef.current !== requestId) return;
      setPositionsPayload(null);
      setPositionsError(
        err instanceof Error
          ? err.message
          : t("dataAnalytics.leaderboard.error.failedToLoadPositions")
      );
    } finally {
      if (positionsRequestIdRef.current === requestId) {
        setPositionsLoading(false);
      }
    }
  }

  useEffect(() => {
    if (!filtersAutoLoadReadyRef.current) {
      filtersAutoLoadReadyRef.current = true;
      void loadLeaderboard(1);
      return;
    }

    const addressChanged = previousAddressRef.current !== filters.address;
    previousAddressRef.current = filters.address;
    const timeoutId = window.setTimeout(
      () => {
        void loadLeaderboard(1);
      },
      addressChanged ? 450 : 0
    );
    return () => window.clearTimeout(timeoutId);
  }, [
    filters.period,
    filters.startDate,
    filters.endDate,
    filters.address,
    filters.pageSize,
    filters.sort,
    t,
  ]);

  useEffect(() => {
    if (!positionsFiltersAutoLoadReadyRef.current) {
      positionsFiltersAutoLoadReadyRef.current = true;
      void loadPositionsLeaderboard(1);
      return;
    }

    const symbolChanged =
      previousPositionSymbolRef.current !== positionsFilters.symbol;
    previousPositionSymbolRef.current = positionsFilters.symbol;
    const timeoutId = window.setTimeout(
      () => {
        void loadPositionsLeaderboard(1);
      },
      symbolChanged ? 450 : 0
    );
    return () => window.clearTimeout(timeoutId);
  }, [positionsFilters.symbol, positionsFilters.pageSize, t]);

  return (
    <PageShell
      pageTitle={t("dataAnalytics.leaderboard.title")}
      contentClassName="max-w-7xl"
    >
      <div className="space-y-6">
        <OdsSegmentedControl
          ariaLabel={t("dataAnalytics.leaderboard.typeAria")}
          items={leaderboardTabItems}
          onValueChange={setActiveLeaderboardTab}
          value={activeLeaderboardTab}
        />

        {activeLeaderboardTab === "trading" ? (
          <section className="rounded-2xl border border-(--line-subtle) bg-(--bg-surface-primary) p-4 shadow-sm sm:p-6">
            <div className="mb-5 space-y-4">
              <h2 className="text-2xl font-semibold tracking-[-0.03em] text-(--fg-primary)">
                {t("dataAnalytics.leaderboard.tradingTitle")}
              </h2>
              <p className="max-w-3xl text-sm leading-6 text-(--fg-secondary)">
                {t("dataAnalytics.leaderboard.tradingDescription")}
              </p>
            </div>

            {error && (
              <div className="mb-5 rounded-lg border border-(--line-negative) bg-(--bg-negative-subtle) px-3 py-2 text-sm text-(--fg-primary)">
                {error}
              </div>
            )}

            <div className="rounded-xl border border-(--line-subtle) bg-(--bg-surface-secondary) p-4">
              <div className="mb-4 flex flex-col gap-3">
                <div className="flex flex-col gap-3 xl:flex-row xl:items-end xl:justify-between">
                  <div className="flex flex-col gap-3 lg:flex-row lg:items-end">
                    <div className="flex flex-wrap items-center gap-2">
                      <DateRangeSegmentedControl
                        onValueChange={period => {
                          if (period !== "custom") updatePeriod(period);
                        }}
                        value={filters.period}
                      />
                      <DateRangeSelector
                        active={filters.period === "custom"}
                        open={dateRangeOpen}
                        startDate={filters.startDate}
                        endDate={filters.endDate}
                        onOpenChange={setDateRangeOpen}
                        onRangeChange={updateCustomDateRange}
                      />
                    </div>

                    <div className="w-full lg:w-[26rem]">
                      <TextInput
                        value={filters.address}
                        placeholder={t(
                          "dataAnalytics.leaderboard.filterByAddress"
                        )}
                        onChange={value => updateFilter("address", value)}
                        onClear={() => updateFilter("address", "")}
                      />
                    </div>
                  </div>

                  <div className="flex flex-col gap-2 xl:items-end">
                    <ColumnVisibilityControl
                      columns={LEADERBOARD_COLUMNS}
                      columnLabels={leaderboardColumnLabels}
                      visibleColumns={visibleColumns}
                      onToggleColumn={toggleColumn}
                      onToggleAll={toggleAllColumns}
                      onResetDefault={() =>
                        setVisibleColumns([...DEFAULT_VISIBLE_COLUMNS])
                      }
                    />
                    {loadedAt && (
                      <span className="text-xs text-(--fg-tertiary)">
                        {t("dataAnalytics.common.lastUpdated", {
                          value: loadedAt.toLocaleString(),
                        })}
                      </span>
                    )}
                  </div>
                </div>
                {loading && (
                  <p className="text-xs text-(--fg-secondary)">
                    {t("dataAnalytics.leaderboard.retrievingRows")}
                  </p>
                )}
              </div>
              {loading ? (
                <LeaderboardSkeleton />
              ) : payload && visiblePayload ? (
                <CompactTable
                  payload={visiblePayload}
                  preferredColumns={visibleColumns}
                  columnLabels={leaderboardColumnLabels}
                  currentPage={currentPage}
                  onPageChange={page => loadLeaderboard(page)}
                  onPageSizeChange={size => {
                    setCurrentPage(1);
                    updateFilter("pageSize", String(size));
                  }}
                  paginationLoading={loading}
                  sortableColumns={SORTABLE_LEADERBOARD_COLUMNS}
                  sortColumn={sortConfig.column}
                  sortDirection={sortConfig.direction}
                  onSortChange={handleSortChange}
                  linkAddressCells
                  emptyDescription={t(
                    "dataAnalytics.leaderboard.noMatchingRows"
                  )}
                  maxColumns={visibleColumns.length}
                  twoDecimalColumns={TRADING_LEADERBOARD_TWO_DECIMAL_COLUMNS}
                />
              ) : (
                <div className="rounded-lg border border-dashed border-(--line-subtle) bg-(--bg-surface-primary) px-4 py-8 text-center">
                  <p className="text-sm font-medium text-(--fg-primary)">
                    {t("dataAnalytics.leaderboard.noLeaderboardLoaded")}
                  </p>
                  <p className="mt-1 text-xs text-(--fg-secondary)">
                    {t(
                      "dataAnalytics.leaderboard.noLeaderboardLoadedDescription"
                    )}
                  </p>
                </div>
              )}
            </div>
          </section>
        ) : (
          <section className="rounded-2xl border border-(--line-subtle) bg-(--bg-surface-primary) p-4 shadow-sm sm:p-6">
            <div className="mb-5 space-y-4">
              <h2 className="text-2xl font-semibold tracking-[-0.03em] text-(--fg-primary)">
                {t("dataAnalytics.leaderboard.positionsTitle")}
              </h2>
              <p className="max-w-3xl text-sm leading-6 text-(--fg-secondary)">
                {t("dataAnalytics.leaderboard.positionsDescription")}
              </p>
            </div>

            {positionsError && (
              <div className="mb-5 rounded-lg border border-(--line-negative) bg-(--bg-negative-subtle) px-3 py-2 text-sm text-(--fg-primary)">
                {positionsError}
              </div>
            )}

            <div className="rounded-xl border border-(--line-subtle) bg-(--bg-surface-secondary) p-4">
              <div className="mb-4 flex flex-col gap-3">
                <div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
                  <div className="w-full lg:max-w-md">
                    <TextInput
                      value={positionsFilters.symbol}
                      placeholder={t(
                        "dataAnalytics.leaderboard.filterBySymbol"
                      )}
                      onChange={value => updatePositionsFilter("symbol", value)}
                      onClear={() => updatePositionsFilter("symbol", "")}
                    />
                  </div>

                  <div className="flex flex-col gap-2 lg:items-end">
                    <ColumnVisibilityControl
                      columns={POSITIONS_LEADERBOARD_COLUMNS}
                      columnLabels={positionsLeaderboardColumnLabels}
                      visibleColumns={visiblePositionsColumns}
                      onToggleColumn={togglePositionsColumn}
                      onToggleAll={toggleAllPositionsColumns}
                      onResetDefault={() =>
                        setVisiblePositionsColumns([
                          ...DEFAULT_VISIBLE_POSITIONS_COLUMNS,
                        ])
                      }
                    />
                    {positionsLoadedAt && (
                      <span className="text-xs text-(--fg-tertiary)">
                        {t("dataAnalytics.common.lastUpdated", {
                          value: positionsLoadedAt.toLocaleString(),
                        })}
                      </span>
                    )}
                  </div>
                </div>
                {positionsLoading && (
                  <p className="text-xs text-(--fg-secondary)">
                    {t("dataAnalytics.leaderboard.retrievingPositionsRows")}
                  </p>
                )}
              </div>
              {positionsLoading ? (
                <LeaderboardSkeleton />
              ) : positionsPayload && visiblePositionsPayload ? (
                <>
                  <CompactTable
                    payload={visiblePositionsPayload}
                    preferredColumns={visiblePositionsColumns}
                    columnLabels={positionsLeaderboardColumnLabels}
                    currentPage={positionsCurrentPage}
                    linkAddressCells
                    emptyDescription={t(
                      "dataAnalytics.leaderboard.noMatchingPositionsRows"
                    )}
                    maxColumns={visiblePositionsColumns.length}
                    twoDecimalColumns={
                      POSITIONS_LEADERBOARD_TWO_DECIMAL_COLUMNS
                    }
                  />
                  <PositionsPaginationControls
                    page={positionsCurrentPage}
                    pageSize={positionsPageSize}
                    rowCount={positionsRows.length}
                    hasNextPage={positionsHasNextPage}
                    loading={positionsLoading}
                    onPageChange={page => loadPositionsLeaderboard(page)}
                    onPageSizeChange={size => {
                      setPositionsCurrentPage(1);
                      updatePositionsFilter("pageSize", String(size));
                    }}
                  />
                </>
              ) : (
                <div className="rounded-lg border border-dashed border-(--line-subtle) bg-(--bg-surface-primary) px-4 py-8 text-center">
                  <p className="text-sm font-medium text-(--fg-primary)">
                    {t("dataAnalytics.leaderboard.noPositionsLoaded")}
                  </p>
                  <p className="mt-1 text-xs text-(--fg-secondary)">
                    {t(
                      "dataAnalytics.leaderboard.noPositionsLoadedDescription"
                    )}
                  </p>
                </div>
              )}
            </div>
          </section>
        )}
      </div>
    </PageShell>
  );
}

function TextInput({
  label,
  value,
  onChange,
  placeholder,
  type = "text",
  inputMode,
  onClear,
}: {
  label?: string;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
  inputMode?: HTMLAttributes<HTMLInputElement>["inputMode"];
  onClear?: () => void;
}) {
  const { t } = useTranslation();
  const showClear = Boolean(onClear && value);
  const accessibleLabel =
    label || placeholder || t("dataAnalytics.common.filter");

  return (
    <OdsInput
      label={label}
      aria-label={accessibleLabel}
      value={value}
      onChange={event => onChange(event.target.value)}
      placeholder={placeholder}
      type={type}
      inputMode={inputMode}
      inputClassName="font-mono placeholder:font-sans"
      action={
        showClear ? (
          <OdsButton
            type="button"
            aria-label={t("dataAnalytics.common.clearLabel", {
              label: accessibleLabel,
            })}
            onClick={onClear}
            size="small"
            variant="secondary"
            className="h-6 w-6 shrink-0 p-0 text-(--fg-tertiary) hover:text-(--fg-primary)"
          >
            <X className="h-3.5 w-3.5" />
          </OdsButton>
        ) : undefined
      }
    />
  );
}

function PositionsPaginationControls({
  page,
  pageSize,
  rowCount,
  hasNextPage,
  loading,
  onPageChange,
  onPageSizeChange,
}: {
  page: number;
  pageSize: number;
  rowCount: number;
  hasNextPage: boolean;
  loading: boolean;
  onPageChange: (page: number) => void | Promise<void>;
  onPageSizeChange: (size: number) => void;
}) {
  const { t } = useTranslation();
  return (
    <div className="mt-3 flex flex-col gap-3 border-t border-(--line-subtle) px-4 py-3 text-sm text-(--fg-secondary) sm:flex-row sm:items-center sm:justify-between">
      <span>
        {t("dataAnalytics.leaderboard.positionsPageSummary", {
          page,
          rows: rowCount,
        })}
      </span>
      <div className="flex items-center gap-2">
        <OdsSelect
          value={String(pageSize)}
          onChange={event => onPageSizeChange(Number(event.target.value))}
          containerClassName="w-[132px]"
          className="h-9"
          disabled={loading}
        >
          {PAGE_SIZE_OPTIONS.map(size => (
            <option key={size} value={size}>
              {t("dataAnalytics.common.perPage", { size })}
            </option>
          ))}
        </OdsSelect>
        <OdsButton
          type="button"
          onClick={() => void onPageChange(page - 1)}
          disabled={loading || page <= 1}
          size="small"
          variant="secondary"
          className="h-8 rounded-full border border-(--line-subtle) bg-transparent px-3 text-xs text-(--fg-primary) hover:bg-(--bg-hover)"
        >
          {t("common.previous")}
        </OdsButton>
        <OdsButton
          type="button"
          onClick={() => void onPageChange(page + 1)}
          disabled={loading || !hasNextPage}
          size="small"
          variant="secondary"
          className="h-8 rounded-full border border-(--line-subtle) bg-transparent px-3 text-xs text-(--fg-primary) hover:bg-(--bg-hover)"
        >
          {t("common.next")}
        </OdsButton>
      </div>
    </div>
  );
}

function ColumnVisibilityControl({
  columns,
  columnLabels,
  visibleColumns,
  onToggleColumn,
  onToggleAll,
  onResetDefault,
}: {
  columns: LeaderboardColumn[];
  columnLabels: Record<string, string>;
  visibleColumns: string[];
  onToggleColumn: (column: string) => void;
  onToggleAll: () => void;
  onResetDefault: () => void;
}) {
  const { t } = useTranslation();
  const visibleColumnSet = new Set(visibleColumns);
  const allSelected = visibleColumns.length === columns.length;

  return (
    <Popover>
      <PopoverTrigger asChild>
        <OdsButton
          type="button"
          size="medium"
          variant="secondary"
          className="h-9 gap-2 px-3 text-sm"
        >
          <Settings2 className="h-4 w-4" />
          {t("dataAnalytics.leaderboard.columns")}
        </OdsButton>
      </PopoverTrigger>
      <PopoverContent
        align="end"
        side="bottom"
        collisionPadding={16}
        sideOffset={8}
        className="max-h-[var(--radix-popover-content-available-height)] w-80 max-w-[90vw] overflow-y-auto rounded-xl border border-(--line-subtle) bg-(--bg-popout) p-3 text-(--fg-primary) shadow-xl"
      >
        <div className="flex flex-col gap-2">
          <div className="flex gap-2">
            <OdsButton
              type="button"
              onClick={onResetDefault}
              size="small"
              variant="primary"
            >
              {t("dataAnalytics.leaderboard.resetToDefault")}
            </OdsButton>
          </div>
          <label className="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-1.5 text-sm text-(--fg-primary) transition-colors hover:bg-(--bg-hover)">
            <OdsCheckbox
              checked={allSelected}
              onCheckedChange={() => onToggleAll()}
            />
            {t("dataAnalytics.leaderboard.toggleAll")}
          </label>
          <hr className="w-full border-(--line-subtle)" />
          {columns.map(column => {
            const checked = visibleColumnSet.has(column.key);
            return (
              <label
                key={column.key}
                className="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-1.5 text-sm text-(--fg-primary) transition-colors hover:bg-(--bg-hover) has-[:disabled]:cursor-not-allowed has-[:disabled]:opacity-60"
              >
                <OdsCheckbox
                  checked={checked}
                  disabled={checked && visibleColumns.length === 1}
                  onCheckedChange={() => onToggleColumn(column.key)}
                />
                {columnLabels[column.key] || column.label}
              </label>
            );
          })}
        </div>
      </PopoverContent>
    </Popover>
  );
}

function LeaderboardSkeleton() {
  return (
    <div className="space-y-3">
      <div className="overflow-hidden rounded-lg border border-(--line-subtle)">
        <div className="grid grid-cols-7 gap-3 bg-(--bg-surface-primary) px-3 py-3">
          {Array.from({ length: 7 }).map((_, index) => (
            <div
              key={index}
              className="h-3 animate-pulse rounded bg-(--bg-surface-secondary)"
            />
          ))}
        </div>
        {Array.from({ length: 8 }).map((_, rowIndex) => (
          <div
            key={rowIndex}
            className="grid grid-cols-7 gap-3 border-t border-(--line-subtle) px-3 py-3"
          >
            {Array.from({ length: 7 }).map((_, columnIndex) => (
              <div
                key={columnIndex}
                className="h-4 animate-pulse rounded bg-(--bg-surface-primary)"
              />
            ))}
          </div>
        ))}
      </div>
      <div className="h-4 w-64 animate-pulse rounded bg-(--bg-surface-primary)" />
    </div>
  );
}
